import { createAnimationTask, addAnimationTask, removeAnimationTask } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

export function startBeacon(manager: AnimationManager, lamp: { intensity: number }, periodSeconds: number): (strength: number) => void {
    let elapsedMs = 0;
    let strength = 1;

    const task = createAnimationTask((mgr, deltaMs) => {
        elapsedMs += deltaMs;
        const periodMs = periodSeconds * 1000;
        const phase = elapsedMs % periodMs;

        if (phase < 100) {
            // Rising: 0 to strength over 0.1s
            lamp.intensity = strength * (phase / 100);
        } else if (phase < 200) {
            // Falling: strength to 0 over 0.1s
            lamp.intensity = strength * (1 - (phase - 100) / 100);
        } else {
            // Off
            lamp.intensity = 0;
        }
    });

    addAnimationTask(manager, task);

    return (newStrength: number) => {
        strength = Math.max(0, Math.min(1, newStrength));
    };
}
```

